10:     fog: opts.fog!=='off',
11:     playerFaction: opts.faction||'human', aiFaction: opts.aiFaction||'undead',
12:     aiPersona: opts.ai||'expander',
13:     seed: (Math.random()*1e9)|0,
14:     entities:[], // {id,owner,kind,type,x,z,hp,maxHp,state,...}
15:     res:[ {gold:220,wood:160,food:2,popCap:5},{gold:220,wood:160,food:2,popCap:5} ],
