22: // grid helpers — world 96x96 units, cell 2
23: export const WORLD=96, CELL=2, GRID=48;
24: export const g2w=(g)=>(g-GRID/2)*CELL+CELL/2;
25: export const w2g=(w)=>Math.max(0,Math.min(GRID-1,Math.floor(w/CELL+GRID/2)));
