38: export function canAfford(st,owner,cost,fm){
39:   const r=st.res[owner];
40:   return r.gold>=(cost.gold||0)*(fm?.cost??1)-1e-6 && r.wood>=(cost.wood||0)*(fm?.cost??1)-1e-6;
41: }
42: export function pay(st,owner,cost,fm){
43:   const r=st.res[owner], m=fm?.cost??1;
44:   r.gold-= (cost.gold||0)*m; r.wood-=(cost.wood||0)*m;
45: }
