52: // --- damage with armor + faction mults
53: export function dealDamage(st,src,tgt,baseDmg){
54:   if(!alive(tgt)||st.over) return;
55:   const armor = tgt.armor||0;
56:   const pierce = src?.armorPierce||0;
57:   let d = Math.max(1, baseDmg - armor*(1-pierce));
58:   if(src?.buff?.rally>0) d *= 1.4;
59:   if(tgt.buff?.rally>0) d = Math.max(1, d-2);
60:   tgt.hp -= d; tgt.flash=0.25;
61:   if(tgt.hp<=0){ tgt.hp=0; tgt.dead=true; tgt.deathT=0.6;
62:     if(tgt.cat==='unit') st.stats.kills[src.owner===0?0:1]+=0; // kills counted by killer below
63:     if(src&&src.owner!==undefined&&tgt.cat==='unit'){ st.stats.kills[src.owner]+=1; if(!st.firstBlood){st.firstBlood=true; st.events.push({t:'toast',msg:`🩸 First blood — ${src.owner===0?'you strike!':'enemy strikes!'}`});} }
64:     if(tgt.cat==='bld'&&tgt.done){ st.events.push({t:'toast',msg:`${tgt.owner===0?'😱 Your':'🔥 Enemy'} ${BUILDINGS[tgt.type]?.name||tgt.type} destroyed!`}); }
65:     if(tgt.type==='townhall'){ checkGameOver(st); }
66:     // Faction signatures: Undead raise the slain, Demon strikes leave a burn.
67:     if(src&&src.owner!==undefined&&tgt.cat==='unit'){
68:       const kf=factionMult(src.owner===0?st.playerFaction:st.aiFaction);
69:       if(kf.burn) tgt.burn={t:3,dps:2,owner:src.owner};
70:       if(kf.raise&&Math.random()<kf.raise){
71:         const u=UNITS.skeleton;
72:         addEntity(st,{cat:'unit',type:'skeleton',owner:src.owner,x:tgt.x+(Math.random()*2-1),z:tgt.z+(Math.random()*2-1),hp:u.hp*kf.hp,maxHp:u.hp*kf.hp,dmg:u.dmg*kf.dmg,armor:u.armor,range:u.range,speed:u.speed*kf.speed,sight:u.sight,armorPierce:u.armorPierce||0,order:null,carry:null,carryAmt:0,cool:0});
73:         st.events.push({t:'toast',msg:'💀 A skeleton rises!'});
74:       }
75:     }
76:   }
77: }
78: export function checkGameOver(st){
79:   const th0=st.entities.some(e=>e.owner===0&&e.type==='townhall'&&alive(e));
80:   const th1=st.entities.some(e=>e.owner===1&&e.type==='townhall'&&alive(e));
81:   if(!th0&&!th1) st.over={win:false,draw:true};
82:   else if(!th1) st.over={win:true};
83:   else if(!th0) st.over={win:false};
84: }
