87: const KEY='kingdoms-rts-save-v1';
88: export function saveGame(st,map){ try{ localStorage.setItem(KEY, JSON.stringify({st:{...st,events:[]},map:{trees:map.trees.map(t=>({x:t.x,z:t.z,amount:t.amount})),gold:map.gold.map(t=>({x:t.x,z:t.z,amount:t.amount}))}})); return true;}catch{return false;} }
89: export function loadGame(){ try{ const s=localStorage.getItem(KEY); return s?JSON.parse(s):null;}catch{return null;} }
90: export function wipeSave(){ try{localStorage.removeItem(KEY);}catch{} }
91: const PKEY='kingdoms-rts-profile-v1';
92: export function getProfile(){ try{return JSON.parse(localStorage.getItem(PKEY)||'{"wins":0,"losses":0,"best":"","ach":[]}');}catch{return{wins:0,losses:0,best:'',ach:[]};} }
93: export function setProfile(p){ try{localStorage.setItem(PKEY,JSON.stringify(p));}catch{} }

