8: export function spawnBase(st,map,owner,fx,fz,faction){
9:   const fm=factionMult(faction);
10:   const thHp=1600*fm.hp*(fm.bldHp??1);
11:   const th=addEntity(st,{cat:'bld',type:'townhall',owner,faction,x:fx,z:fz,hp:thHp,maxHp:thHp,done:true,size:3.4,sight:12,armor:2,queue:[],prog:0});
12:   for(let i=0;i<2;i++) addEntity(st,{cat:'unit',type:'peasant',owner,faction,x:fx+4+i*2.5,z:fz+4,hp:70*fm.hp,maxHp:70*fm.hp,dmg:4,armor:0,speed:5.2,sight:9,armorPierce:0,order:null,carry:null,carryAmt:0,cool:0});
13:   return th;
14: }
