16: let blockedCache=null, blockedTick=-1;
17: export function tick(st,map,dt){
18:   st.events=[];
19:   st.t+=dt; st.tick++;
20:   const fm=[factionMult(st.playerFaction),factionMult(st.aiFaction)];
21:   if(st.tick%20===0) updateFog(st,map);
22:   if(blockedTick!==st.tick){ blockedCache=buildBlocked(st,map); blockedTick=st.tick; }
23: 
24:   // economy trickle: farms give food
25:   if(st.tick%50===0){ for(let o=0;o<2;o++){ const farms=st.entities.filter(e=>e.owner===o&&e.type==='farm'&&e.done&&alive(e)).length; st.res[o].food+=farms*1; }
26:     // Wilde signature: the forest regrows under their care.
27:     if(fm[0].regrow||fm[1].regrow){ for(const tr of map.trees){ if(tr.amount>0&&tr.amount<180) tr.amount=Math.min(180,tr.amount+2); } }
28:   }
29:   // Three Bells pacing: 3:00 raid, 6:00 turn, 9:00 war. Tutorial has no clock.
30:   const bellAt=st.tutorial?undefined:[180,360,540][st.bells||0];
31:   if(bellAt!==undefined&&st.t>=bellAt){
32:     st.bells=(st.bells||0)+1;
33:     const msg=st.bells===1?'🔔 First Bell — the raid begins!':st.bells===2?'🔔 Second Bell — the map turns.':'🔔 Third Bell — war without end!';
34:     st.events.push({t:'toast',msg});
35:     st.events.push({t:'bell',n:st.bells});
36:   }
37: 
38:   for(const e of st.entities){
39:     if(e.dead) continue;
40:     if(e.flash>0)e.flash-=dt;
41:     if(e.cat==='bld'){
42:       if(e.repair>0){ e.repair-=dt; e.hp=Math.min(e.maxHp,e.hp+e.repairRate*dt); }
43:       // construction progress
44:       if(!e.done){ e.prog+=(dt/e.time)*(e.builder?1:0.15); if(e.prog>=1){e.done=true;e.prog=1;e.hp=e.maxHp;st.events.push({t:'toast',msg:`${e.owner===0?'✅':'🏗️'} ${BUILDINGS[e.type].name} ${e.owner===0?'ready!':'built by enemy!'}`});} continue; }
45:       // production queue
46:       if(e.queue&&e.queue.length){
47:         const u=e.queue[0]; e.prog+=dt*(fm[e.owner].produce??1)/UNITS[u].time;
48:         if(e.prog>=1){ e.queue.shift(); e.prog=0;
49:           const f=fm[e.owner];
50:           addEntity(st,{cat:'unit',type:u,owner:e.owner,faction:e.faction,x:e.x+2.5,z:e.z+2.5,hp:UNITS[u].hp*f.hp,maxHp:UNITS[u].hp*f.hp,dmg:UNITS[u].dmg*(u==='archer'?(f.archer??f.dmg):f.dmg)*(e.buffDmg||1),armor:UNITS[u].armor,range:UNITS[u].range,speed:UNITS[u].speed*f.speed,sight:UNITS[u].sight,armorPierce:UNITS[u].armorPierce||0,order:null,carry:null,carryAmt:0,cool:0});
51:         }
52:       }
53:       // tower shooting
54:       if(e.type==='tower'){ e.cool=(e.cool||0)-dt; if(e.cool<=0){ const tgt=nearestEnemy(st,e,BUILDINGS.tower.range,e.owner); if(tgt){ e.cool=1.4; fireProjectile(st,e,tgt,BUILDINGS.tower.dmg*fm[e.owner].dmg);} } }
55:       // blacksmith instant buff
56:       if(e.type==='blacksmith'&&!e.applied){ e.applied=true; for(const u of st.entities) if(u.owner===e.owner&&u.cat==='unit'){u.dmg+=2;u.maxHp+=20;u.hp+=20;} }
57:     } else {
58:       // unit AI: abilities, buffs, burn, regen, then movement/combat
59:       if(e.abilityCd>0) e.abilityCd-=dt;
60:       if(e.buff){ for(const k in e.buff){ e.buff[k]-=dt; if(e.buff[k]<=0) delete e.buff[k]; } }
61:       if(e.burn&&e.burn.t>0){
62:         e.burn.t-=dt; e.hp-=e.burn.dps*dt;
63:         if(e.hp<=0){ e.hp=0; e.dead=true; e.deathT=0.6; continue; }
64:       }
65:       const efm=fm[e.owner];
66:       if(efm.regen&&e.hp<e.maxHp){
67:         let threat=false;
68:         for(const o of st.entities){
69:           if(o.dead||o.owner===e.owner||o.owner===2||o.cat==='proj') continue;
70:           if(Math.hypot(o.x-e.x,o.z-e.z)<9){ threat=true; break; }
71:         }
72:         if(!threat) e.hp=Math.min(e.maxHp,e.hp+efm.regen*dt);
73:       }
74:       if(e.owner===1&&(e.abilityCd||0)<=0&&(e.type==='warrior'||e.type==='archer'||e.type==='knight')){
75:         if(nearestEnemy(st,e,10,e.owner)) useAbility(st,e);
76:       }
77:       e.cool-=dt;
78:       updateUnit(st,map,e,dt,fm[e.owner],blockedCache);
79:       // QoL: idle player peasants auto-seek wood after 6s (classic RTS behavior).
80:       // In Mission 1 they stay inside the clearing so the fixed camera keeps them
81:       // on screen and tappable.
82:       if(e.owner===0&&e.type==='peasant'&&e.order&&e.order.kind==='idle'){
83:         e.idleT=(e.idleT||0)+dt;
84:         if(e.idleT>6){ e.idleT=0; const i=findResource(map,e.x,e.z,'tree',st,st.tutorial?15:Infinity); if(i>=0) orderGather(st,map,e,'tree',i); }
85:       } else e.idleT=0;
86:     }
87:   }
88:   // projectiles
89:   for(const e of st.entities){
90:     if(e.cat!=='proj'||e.dead)continue;
91:     e.life-=dt;
92:     const tgt=byId(st,e.tgt);
93:     if(!tgt||tgt.dead||e.life<=0){e.dead=true;continue;}
94:     const dx=tgt.x-e.x,dz=tgt.z-e.z,d=Math.hypot(dx,dz);
95:     const sp=22*dt;
96:     if(d<0.8){ dealDamage(st,e,tgt,e.dmg); e.dead=true; spawnHit(st,tgt.x,tgt.z); }
97:     else { e.x+=dx/d*sp; e.z+=dz/d*sp; }
98:   }
99:   st.entities=st.entities.filter(e=>!e.dead||(e.deathT??0)>0);
100:   for(const e of st.entities) if(e.dead&&e.deathT!==undefined) e.deathT-=dt;
101:   st.entities=st.entities.filter(e=>!(e.dead&&e.cat==='proj')&&!(e.dead&&e.cat==='unit'&&(e.deathT??0)<=0));
102:   // keep rubble of buildings briefly? remove dead buildings except townhall rubble
103:   st.entities=st.entities.filter(e=>!(e.dead&&e.cat==='bld'&&e.type!=='townhall'));
104: }
