106: function spawnHit(st,x,z){ st.events.push({t:'hit',x,z}); }
107: function nearestEnemy(st,e,range,owner){
108:   let best=null,bd=range;
109:   for(const o of st.entities){ if(o.dead||o.owner===owner||o.owner===2)continue; if(o.cat==='proj')continue; if(o.cat==='res')continue;
110:     const d=Math.hypot(o.x-e.x,o.z-e.z); if(d<bd){bd=d;best=o;} }
111:   return best;
112: }
