114: function updateUnit(st,map,e,dt,fm,blocked){
115:   const o=e.order;
116:   // auto-acquire for military
117:   if((e.type==='warrior'||e.type==='archer'||e.type==='knight'||e.type==='skeleton')&&(!o||o.kind==='move'||o.kind==='idle')){
118:     if(e.cool<=0){ const tgt=nearestEnemy(st,e,(e.type==='archer'?9:4)*(e.type==='archer'?(fm.range??1):1),e.owner); if(tgt){ e.order={kind:'attack',id:tgt.id}; } }
119:   }
120:   if(!o){ e.order={kind:'idle'}; return; }
121:   if(o.kind==='idle')return;
122:   if(o.kind==='move'||o.kind==='attackmove'){
123:     if(!o.path){ o.path=findPath(w2g(e.x),w2g(e.z),w2g(o.x),w2g(o.z),blocked)||[{x:o.x,z:o.z}]; o.pi=0; }
124:     const wp=o.path[o.pi];
125:     if(!wp){e.order={kind:'idle'};return;}
126:     if(moveToward(e,wp,dt)){ o.pi++; if(o.pi>=o.path.length){e.order={kind:'idle'};} }
127:     if(o.kind==='attackmove'&&e.cool<=0){ const tgt=nearestEnemy(st,e,7,e.owner); if(tgt){e.order={kind:'attack',id:tgt.id};return;} }
128:     return;
129:   }
130:   if(o.kind==='attack'){
131:     const tgt=byId(st,o.id);
132:     if(!tgt||tgt.dead){e.order={kind:'idle'};return;}
133:     const range=(UNITS[e.type].range||1.6)*(e.type==='archer'?(fm.range??1):1);
134:     const reach=range+(tgt.cat==='bld'?(tgt.size||0):0);
135:     const d=Math.hypot(tgt.x-e.x,tgt.z-e.z);
136:     if(d<=reach){
137:       if(e.cool<=0){
138:         e.cool=e.type==='archer'?1.3:1.0;
139:         let dmg=e.dmg;
140:         if(e.chargeHit){ dmg*=1.5; e.chargeHit=false; }
141:         if(e.type==='archer') fireProjectile(st,e,tgt,dmg);
142:         else { dealDamage(st,e,tgt,dmg); st.events.push({t:'hit',x:tgt.x,z:tgt.z}); }
143:         e.face=tgt;
144:       }
145:     } else {
146:       if(!o.path||(o.chaseT??0)<=0){
147:         o.path=findPath(w2g(e.x),w2g(e.z),w2g(tgt.x),w2g(tgt.z),blocked)||[{x:tgt.x,z:tgt.z}];
148:         o.pi=0; o.chaseT=0.5;
149:       }
150:       o.chaseT-=dt;
151:       const wp=o.path[o.pi];
152:       if(wp&&moveToward(e,wp,dt)){ o.pi++; if(o.pi>=o.path.length){o.path=null;o.chaseT=0;} }
153:       if(Math.hypot(tgt.x-e.x,tgt.z-e.z)>reach+14) e.order={kind:'idle'};
154:     }
155:     return;
156:   }
157:   if(o.kind==='gather'){
158:     const node=o.node; // {kind:'tree'|'gold', ref}
159:     const arr=o.kind2==='gold'?map.gold:map.trees;
160:     const n=arr[o.idx];
161:     if(!n||n.amount<=0){ // find another
162:       const ni=findResource(map,e.x,e.z,o.kind2,st);
163:       if(ni>=0){o.idx=ni;} else {e.order={kind:'idle'};e.carry=null;return;}
164:       return;
165:     }
166:     const d=Math.hypot(n.x-e.x,n.z-e.z);
167:     if(e.carryAmt>0){ // return home
168:       const hall=nearestHall(st,e.owner,e.x,e.z);
169:       if(!hall){e.order={kind:'idle'};return;}
170:       if(Math.hypot(hall.x-e.x,hall.z-e.z)<4){
171:         const rkey=o.kind2==='gold'?'gold':'wood';
172:         const mult=(o.kind2==='gold'?(fm.gold??1):(fm.wood??1))*(fm.gather??1);
173:         st.res[e.owner][rkey]+=e.carryAmt*mult; e.carryAmt=0; e.carry=null;
174:         st.events.push({t:'gather',x:e.x,z:e.z,kind:o.kind2});
175:       } else moveToward(e,hall,dt);
176:       return;
177:     }
178:     if(d<2.2){ e.gatherT=(e.gatherT||0)+dt; if(e.gatherT>1.2){e.gatherT=0; const take=Math.min(UNITS.peasant.gather,n.amount); n.amount-=take; e.carryAmt=take; e.carry=o.kind2;} }
179:     else moveToward(e,n,dt);
180:     return;
181:   }
182:   if(o.kind==='build'){
183:     const b=byId(st,o.id);
184:     if(!b||b.dead){e.order={kind:'idle'};return;}
185:     if(Math.hypot(b.x-e.x,b.z-e.z)<b.size+1.5){ b.builder=true; e.building=true; if(b.done){e.order={kind:'idle'};e.building=false;} }
186:     else { e.building=false; moveToward(e,b,dt); }
187:     return;
188:   }
189: }
