191: function moveToward(e,wp,dt){
192:   const dx=wp.x-e.x,dz=wp.z-e.z,d=Math.hypot(dx,dz);
193:   if(d<0.4) return true;
194:   const sp=(e.speed||5)*(e.buff?.charge>0?2.2:1)*dt;
195:   e.x+=dx/d*Math.min(sp,d); e.z+=dz/d*Math.min(sp,d);
196:   e.face={x:wp.x,z:wp.z};
197:   return d<0.6;
198: }
199: export function orderMove(st,e,x,z,attack){
200:   // formation offsets applied by caller
201:   e.order={kind:attack?'attackmove':'move',x,z,path:null,pi:0}; e.building=false;
202: }
203: export function orderAttack(st,e,id){ e.order={kind:'attack',id}; e.building=false; }
204: export function orderGather(st,map,e,kind2,idx){ e.order={kind:'gather',kind2,idx}; }
205: export function orderBuild(st,e,id){ e.order={kind:'build',id}; }
206: export function findResource(map,x,z,kind2,st,maxR=Infinity){
207:   const arr=kind2==='gold'?map.gold:map.trees;
208:   let bi=-1,bd=maxR*maxR;
209:   for(let i=0;i<arr.length;i++){ if(arr[i].amount<=0)continue; const d=(arr[i].x-x)**2+(arr[i].z-z)**2; if(d<bd){bd=d;bi=i;} }
210:   return bi;
211: }
212: export function nearestHall(st,owner,x,z){
213:   let best=null,bd=1e9;
214:   for(const e of st.entities){ if(e.dead||e.owner!==owner||e.cat!=='bld')continue; if(e.type!=='townhall'&&e.type!=='farm')continue; if(!e.done)continue; const d=(e.x-x)**2+(e.z-z)**2; if(d<bd){bd=d;best=e;} }
215:   return best;
216: }
217: export function fireProjectile(st,src,tgt,dmg){
218:   st.entities.push({id:(Math.random()*1e9)|0,cat:'proj',owner:src.owner,x:src.x,z:src.z-0.5,tgt:tgt.id,dmg,life:2,armorPierce:src.armorPierce||0});
219: }

